CREATE INDEX idx_chat_events_meta ON chat_events( chat_id, id, type, json_extract(data, '$.id'), json_extract(data, '$.name'), json_extract(data, '$.parent'), json_extract(data, '$.tool_use_id'), json_extract(data, '$.task_id'), json_extract(data, '$.status'), length(data) );
CREATE INDEX idx_chat_groups_project ON chat_groups(project_id, position);
