CREATE TABLE agent_sessions ( session_id TEXT PRIMARY KEY CHECK (session_id <> ''), provider TEXT NOT NULL CHECK (provider <> ''), project_id INTEGER REFERENCES projects(id) ON DELETE SET NULL, cwd TEXT NOT NULL CHECK (cwd <> ''), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ) STRICT;
CREATE VIRTUAL TABLE chat_event_search USING fts5(text, content = 'chat_event_texts', content_rowid = 'id', tokenize = 'trigram');
CREATE TABLE 'chat_event_search_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TABLE 'chat_event_search_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE 'chat_event_search_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE 'chat_event_search_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE chat_events ( id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER NOT NULL REFERENCES chats(id) ON DELETE CASCADE, type TEXT NOT NULL, data TEXT NOT NULL CHECK (json_valid(data) AND json_type(data) = 'object'), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), text TEXT GENERATED ALWAYS AS ( CASE WHEN type = 'user' OR (type = 'text' AND json_extract(data, '$.parent') IS NULL) THEN json_extract(data, '$.text') END ) VIRTUAL ) STRICT;
CREATE TABLE chat_groups ( id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL CHECK (name <> ''), hue INTEGER NOT NULL CHECK (hue BETWEEN 0 AND 359), position INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ) STRICT;
CREATE TABLE chat_image_cache ( chat_id INTEGER NOT NULL REFERENCES chats(id) ON DELETE CASCADE, key TEXT NOT NULL CHECK (key <> ''), host TEXT NOT NULL CHECK (host <> ''), content_type TEXT NOT NULL CHECK (content_type <> ''), size INTEGER NOT NULL CHECK (size >= 0), fetched_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY (chat_id, key) ) STRICT;
CREATE TABLE chat_image_hosts ( chat_id INTEGER NOT NULL REFERENCES chats(id) ON DELETE CASCADE, host TEXT NOT NULL CHECK (host <> ''), allowed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY (chat_id, host) ) STRICT;
CREATE TABLE chat_outbox ( chat_id INTEGER PRIMARY KEY REFERENCES chats(id) ON DELETE CASCADE, now TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(now) AND json_type(now) = 'array'), later TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(later) AND json_type(later) = 'array'), stops TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(stops) AND json_type(stops) = 'array'), paused INTEGER NOT NULL DEFAULT 0 CHECK (paused IN (0, 1)) ) STRICT;
CREATE TABLE chat_provider_handoffs ( chat_id INTEGER PRIMARY KEY REFERENCES chats(id) ON DELETE CASCADE, event_id INTEGER NOT NULL REFERENCES chat_events(id) ON DELETE CASCADE, provider TEXT NOT NULL CHECK (provider <> ''), context TEXT NOT NULL CHECK (context <> ''), state TEXT NOT NULL, error TEXT, last_event_id INTEGER CHECK (last_event_id > 0), queue_was_paused INTEGER NOT NULL DEFAULT 0 CHECK (queue_was_paused IN (0, 1)) ) STRICT;
CREATE TABLE chat_provider_sessions ( chat_id INTEGER NOT NULL REFERENCES chats(id) ON DELETE CASCADE, provider TEXT NOT NULL CHECK (provider <> ''), session_id TEXT NOT NULL CHECK (session_id <> ''), last_event_id INTEGER CHECK (last_event_id > 0), PRIMARY KEY (chat_id, provider) ) STRICT;
CREATE TABLE chats ( id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, group_id INTEGER REFERENCES chat_groups(id) ON DELETE SET NULL, parent_chat_id INTEGER REFERENCES chats(id) ON DELETE CASCADE, parent_event_id INTEGER CHECK (parent_event_id > 0), note_path TEXT CHECK (note_path <> ''), github_repo TEXT CHECK (github_repo <> ''), github_number INTEGER CHECK (github_number > 0), github_kind TEXT CHECK (github_kind <> ''), title TEXT NOT NULL DEFAULT '', provider TEXT NOT NULL, model TEXT, effort TEXT, permission_mode TEXT NOT NULL, fast_mode INTEGER NOT NULL DEFAULT 0 CHECK (fast_mode IN (0, 1)), sandbox_enabled INTEGER NOT NULL DEFAULT 1 CHECK (sandbox_enabled IN (0, 1)), edit_scope_enabled INTEGER NOT NULL DEFAULT 1 CHECK (edit_scope_enabled IN (0, 1)), untracked_only INTEGER NOT NULL DEFAULT 0 CHECK (untracked_only IN (0, 1)), worktree_path TEXT CHECK (worktree_path <> ''), branch TEXT CHECK (branch <> ''), finished_worktree_branch TEXT CHECK (finished_worktree_branch <> ''), status TEXT NOT NULL, session_id TEXT, error TEXT, turn_started_at TEXT, unread INTEGER NOT NULL DEFAULT 0 CHECK (unread IN (0, 1)), resume_pending INTEGER NOT NULL DEFAULT 0 CHECK (resume_pending IN (0, 1)), ai_generation INTEGER NOT NULL DEFAULT 0 CHECK (ai_generation >= 0), cost_usd REAL NOT NULL DEFAULT 0 CHECK (cost_usd >= 0), num_turns INTEGER NOT NULL DEFAULT 0 CHECK (num_turns >= 0), context_tokens INTEGER, context_window INTEGER, pinned INTEGER NOT NULL DEFAULT 0 CHECK (pinned IN (0, 1)), position INTEGER, archived_at TEXT, archived_with_parent INTEGER NOT NULL DEFAULT 0 CHECK (archived_with_parent IN (0, 1)), trashed_at TEXT, trashed_with TEXT CHECK (trashed_with <> ''), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), active_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK ((github_repo IS NULL) = (github_number IS NULL) AND (github_repo IS NULL) = (github_kind IS NULL)) ) STRICT;
CREATE TABLE db_connections ( id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL CHECK (name <> ''), engine TEXT NOT NULL, environment TEXT NOT NULL, host TEXT CHECK (host <> ''), port INTEGER CHECK (port > 0), database TEXT CHECK (database <> ''), username TEXT CHECK (username <> ''), file_path TEXT CHECK (file_path <> ''), worktree_path TEXT CHECK (worktree_path <> ''), ssl TEXT CHECK (json_valid(ssl) AND json_type(ssl) = 'object'), ssh TEXT CHECK (json_valid(ssh) AND json_type(ssh) = 'object'), prep TEXT CHECK (json_valid(prep) AND json_type(prep) = 'object'), prep_confirmed TEXT CHECK (prep_confirmed <> ''), note_path TEXT CHECK (note_path <> ''), ai_access TEXT NOT NULL, ai_username TEXT CHECK (ai_username <> ''), read_only INTEGER NOT NULL CHECK (read_only IN (0, 1)), write_check TEXT NOT NULL DEFAULT 'dangerous', check_on TEXT CHECK (check_on <> ''), check_note TEXT CHECK (check_note <> ''), position INTEGER NOT NULL, last_connected_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ) STRICT;
CREATE TABLE db_er_layouts ( connection_id INTEGER NOT NULL REFERENCES db_connections(id) ON DELETE CASCADE, scope TEXT NOT NULL CHECK (scope <> ''), positions TEXT NOT NULL CHECK (json_valid(positions) AND json_type(positions) = 'object'), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY (connection_id, scope) ) STRICT;
CREATE TABLE db_prep_runs ( id INTEGER PRIMARY KEY AUTOINCREMENT, connection_id INTEGER NOT NULL REFERENCES db_connections(id) ON DELETE CASCADE, kind TEXT NOT NULL, command TEXT NOT NULL CHECK (command <> ''), ok INTEGER NOT NULL CHECK (ok IN (0, 1)), ran_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ) STRICT;
CREATE TABLE db_query_history ( id INTEGER PRIMARY KEY AUTOINCREMENT, connection_id INTEGER NOT NULL REFERENCES db_connections(id) ON DELETE CASCADE, sql TEXT NOT NULL CHECK (sql <> ''), ran_by TEXT NOT NULL, chat_id INTEGER REFERENCES chats(id) ON DELETE SET NULL, duration_ms INTEGER, row_count INTEGER, error TEXT, ran_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ) STRICT;
CREATE TABLE devices ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL CHECK (name <> ''), token_hash TEXT NOT NULL UNIQUE CHECK (token_hash <> ''), access TEXT NOT NULL DEFAULT 'full' CHECK (access <> ''), push TEXT CHECK (push IS NULL OR (json_valid(push) AND json_type(push) = 'object')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), last_used_at TEXT ) STRICT;
CREATE TABLE github_ci_notices ( project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, run_id INTEGER NOT NULL CHECK (run_id > 0), notified_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY (project_id, run_id) ) STRICT;
CREATE TABLE meta ( key TEXT PRIMARY KEY, value TEXT NOT NULL ) STRICT;
CREATE TABLE note_image_cache ( project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, path TEXT NOT NULL CHECK (path <> ''), key TEXT NOT NULL CHECK (key <> ''), host TEXT NOT NULL CHECK (host <> ''), content_type TEXT NOT NULL CHECK (content_type <> ''), size INTEGER NOT NULL CHECK (size >= 0), fetched_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY (project_id, path, key) ) STRICT;
CREATE TABLE note_image_hosts ( project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, path TEXT NOT NULL CHECK (path <> ''), host TEXT NOT NULL CHECK (host <> ''), allowed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY (project_id, path, host) ) STRICT;
CREATE TABLE project_ai_defaults ( project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, provider TEXT NOT NULL CHECK (provider <> ''), options TEXT NOT NULL CHECK (json_valid(options) AND json_type(options) = 'object'), PRIMARY KEY (project_id, provider) ) STRICT;
CREATE TABLE projects ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL CHECK (name <> ''), description TEXT CHECK (description <> ''), repo_path TEXT NOT NULL UNIQUE, provider TEXT NOT NULL, hue INTEGER NOT NULL CHECK (hue BETWEEN 0 AND 359), tags TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(tags) AND json_type(tags) = 'array'), reference_paths TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(reference_paths) AND json_type(reference_paths) = 'array'), note_folder TEXT CHECK (note_folder <> ''), note_dir TEXT CHECK (note_dir <> ''), pre_compact_prompt TEXT CHECK (pre_compact_prompt <> ''), pre_compact_enabled INTEGER NOT NULL DEFAULT 1 CHECK (pre_compact_enabled IN (0, 1)), post_compact_prompt TEXT CHECK (post_compact_prompt <> ''), post_compact_enabled INTEGER NOT NULL DEFAULT 1 CHECK (post_compact_enabled IN (0, 1)), github_account TEXT CHECK (github_account <> ''), github_remote TEXT CHECK (github_remote <> ''), pr_watch INTEGER NOT NULL DEFAULT 1 CHECK (pr_watch IN (0, 1)), ci_watch INTEGER NOT NULL DEFAULT 1 CHECK (ci_watch IN (0, 1)), position INTEGER NOT NULL, pinned INTEGER NOT NULL DEFAULT 0 CHECK (pinned IN (0, 1)), archived_at TEXT, trashed_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) , kind TEXT CHECK (kind <> '')) STRICT;
CREATE TABLE secrets ( key TEXT PRIMARY KEY, value TEXT NOT NULL CHECK (value <> '') ) STRICT;
CREATE TABLE settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL CHECK (json_valid(value)) ) STRICT;
CREATE TABLE snippets ( id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER REFERENCES projects(id) ON DELETE CASCADE, label TEXT CHECK (label <> ''), text TEXT NOT NULL CHECK (text <> ''), position INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ) STRICT;
CREATE TABLE trash_items ( id TEXT PRIMARY KEY CHECK (id <> ''), project_id INTEGER REFERENCES projects(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind <> ''), label TEXT NOT NULL CHECK (label <> ''), origin TEXT CHECK (origin <> ''), is_dir INTEGER NOT NULL DEFAULT 0 CHECK (is_dir IN (0, 1)), size INTEGER CHECK (size IS NULL OR size >= 0), chat_id INTEGER, by_chat_id INTEGER, details TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(details) AND json_type(details) = 'object'), trashed_at TEXT NOT NULL ) STRICT;
CREATE TABLE worktree_pr_dismissals ( project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, pr_number INTEGER NOT NULL CHECK (pr_number > 0), dismissed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY (project_id, pr_number) ) STRICT;
CREATE TABLE worktrees ( path TEXT PRIMARY KEY CHECK (path <> ''), project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, hue INTEGER CHECK (hue IS NULL OR hue BETWEEN 0 AND 359), env_band INTEGER UNIQUE CHECK (env_band IS NULL OR env_band > 0), env_host TEXT CHECK (env_host <> ''), env_slots TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(env_slots) AND json_type(env_slots) = 'array'), env_compose_names TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(env_compose_names) AND json_type(env_compose_names) = 'array'), env_rewritten TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(env_rewritten) AND json_type(env_rewritten) = 'array'), env_issues TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(env_issues) AND json_type(env_issues) = 'array'), env_blocked TEXT CHECK (env_blocked <> ''), env_created_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ) STRICT;
CREATE TRIGGER chat_events_search_delete AFTER DELETE ON chat_events WHEN old.text IS NOT NULL BEGIN INSERT INTO chat_event_search (chat_event_search, rowid, text) VALUES ('delete', old.id, old.text); END;
CREATE TRIGGER chat_events_search_insert AFTER INSERT ON chat_events WHEN new.text IS NOT NULL BEGIN INSERT INTO chat_event_search (rowid, text) VALUES (new.id, new.text); END;
CREATE TRIGGER chat_events_search_update AFTER UPDATE OF type, data ON chat_events BEGIN INSERT INTO chat_event_search (chat_event_search, rowid, text) SELECT 'delete', old.id, old.text WHERE old.text IS NOT NULL; INSERT INTO chat_event_search (rowid, text) SELECT new.id, new.text WHERE new.text IS NOT NULL; END;
CREATE TRIGGER chats_group_project_insert BEFORE INSERT ON chats WHEN new.group_id IS NOT NULL AND (SELECT project_id FROM chat_groups WHERE id = new.group_id) IS NOT new.project_id BEGIN SELECT RAISE(ABORT, 'chat group belongs to another project'); END;
CREATE TRIGGER chats_group_project_update BEFORE UPDATE OF group_id, project_id ON chats WHEN new.group_id IS NOT NULL AND (SELECT project_id FROM chat_groups WHERE id = new.group_id) IS NOT new.project_id BEGIN SELECT RAISE(ABORT, 'chat group belongs to another project'); END;
CREATE TRIGGER db_connections_drop_secrets AFTER DELETE ON db_connections BEGIN DELETE FROM secrets WHERE key LIKE 'db_connection:' || OLD.id || ':%'; END;
CREATE VIEW chat_event_texts AS SELECT id, text FROM chat_events WHERE text IS NOT NULL;
